// Generated by tabmill (templates/extension/_shared) — do not edit (ADR-0008).
// Run a runtime content script in the user's tab (activeTab + scripting) and return its
// typed result. Shared by every extension that reads the current page.

export class UserError extends Error {}

/** Paths WXT knows exist in the build, e.g. "/content-scripts/extract.js". */
type ScriptFile = NonNullable<Parameters<typeof browser.scripting.executeScript>[0]["files"]>[number];

export const RESTRICTED_PAGE =
  "This page can't be read. Browser pages (chrome://), the Chrome Web Store, and other " +
  "protected pages are off-limits to extensions — or click the toolbar button again on this " +
  "page to grant access.";

export async function targetTabId(): Promise<number> {
  // `?tabId=` lets smoke tests drive the UI as a normal page (no toolbar click in tests).
  const override = new URLSearchParams(location.search).get("tabId");
  if (override) return Number(override);
  const [tab] = await browser.tabs.query({ active: true, currentWindow: true });
  if (tab?.id === undefined) throw new UserError("No active tab.");
  return tab.id;
}

/** Inject a built content script and return its main() result if `guard` accepts it. */
export async function runInTab<T>(file: ScriptFile, guard: (v: unknown) => v is T): Promise<T> {
  const tabId = await targetTabId();
  let result: unknown;
  try {
    const [injection] = await browser.scripting.executeScript({
      target: { tabId },
      files: [file],
    });
    result = injection?.result;
  } catch {
    throw new UserError(RESTRICTED_PAGE);
  }
  if (!guard(result)) throw new UserError("Couldn't read this page.");
  return result;
}
